import assert from 'node:assert/strict';
import { temporalCliArgs } from './src/brain-context/temporal.ts';
import { compilerRetrievalLimits, renderCompilerPromptEvidenceContext } from './src/brain-context/render.ts';
const args=temporalCliArgs({view:'transition',request_time:'2026-09-10T00:00:00Z',known_at:'2026-09-10',transition:{from:'2026-09-01',to:'2026-09-09'}});
assert.deepEqual(args,['--temporal-view','transition','--request-time','2026-09-10T00:00:00Z','--known-at','2026-09-10','--transition-from','2026-09-01','--transition-to','2026-09-09']);
const retrieval={contractVersion:'3',query:{projectResolution:{status:'matched',projectId:'anvil',page:'projects/anvil.md',matchedBy:'alias'}},evidence:[],diagnostics:[{code:'PROVIDER_FAILED',message:'x',provider:null,details:{}}],omissions:[{candidateId:'x',reason:'byte_limit',estimatedBytes:null}],stop:{reason:'provider_degraded',sufficient:false,detail:'x'},reporting:{diagnostics:{total:2,returned:1},omissions:{total:2,returned:1}}};
