const v3=renderCompilerPromptEvidenceContext(retrieval);
const v1=renderCompilerPromptEvidenceContext({...retrieval,contractVersion:'1'});
assert.deepEqual(Object.fromEntries(Object.entries(v3).map(([k,v])=>[k,typeof v])),{markdown:'string',renderedBytes:'number',truncated:'boolean',attemptedBytes:'number',guidanceBytes:'number',retrievedContextBytes:'number',framingBytes:'number'});
assert.ok(v3.markdown.includes('projects/anvil.md'));
assert.ok(!v1.markdown.includes('projects/anvil.md'));
console.log(JSON.stringify({node:process.version,source_commit:'4d5afbcb54ab9d4bbb12e39357108b3caa4f6874',cases:3,status:'passed',scope:'Runtime behavior portions of the three independently authored answers; no agent execution or TypeScript typecheck claim.'}));
